use serde::{Deserialize,Serialize};
use std::{collections::VecDeque,sync::Mutex,time::{Duration,Instant}};
use windows_sys::Win32::UI::{Input::KeyboardAndMouse::*,WindowsAndMessaging::{GetSystemMetrics,SetCursorPos,SM_XVIRTUALSCREEN,SM_YVIRTUALSCREEN,SM_CXVIRTUALSCREEN,SM_CYVIRTUALSCREEN}};

const MAX_SESSION:Duration=Duration::from_secs(300);const MAX_ROUNDS:u8=12;const MAX_FAILURES:u8=3;const MAX_TEXT:usize=500;
#[derive(Debug,Clone,Copy,PartialEq,Serialize)] #[serde(rename_all="camelCase")] pub enum Permission{Normal,SeeScreen,ControlScreen}
#[derive(Debug,Deserialize,Serialize)] #[serde(tag="type",rename_all="snake_case")] pub enum Action{MovePointer{x:i32,y:i32},Click{x:i32,y:i32},DoubleClick{x:i32,y:i32},RightClick{x:i32,y:i32},SemanticClick{window:String,name:String},Scroll{delta:i32},TypeText{text:String},PressKey{key:String},KeyCombination{keys:Vec<String>},Wait{milliseconds:u64},OpenKnownApp{app:String}}
#[derive(Debug,Clone,PartialEq)] pub enum Decision{Execute,Confirm(String)}
struct Session{permission:Permission,started:Option<Instant>,rounds:u8,failures:u8,cancelled:bool,recent:VecDeque<String>}
pub struct ControlState(Mutex<Session>);
impl Default for ControlState{fn default()->Self{Self(Mutex::new(Session{permission:Permission::Normal,started:None,rounds:0,failures:0,cancelled:false,recent:VecDeque::new()}))}}
impl ControlState{
 pub fn authorize_once(&self){let mut s=self.0.lock().unwrap();s.permission=Permission::SeeScreen;s.cancelled=false;}
 pub fn start(&self){let mut s=self.0.lock().unwrap();*s=Session{permission:Permission::ControlScreen,started:Some(Instant::now()),rounds:0,failures:0,cancelled:false,recent:VecDeque::new()};}
 pub fn stop(&self){let mut s=self.0.lock().unwrap();s.permission=Permission::Normal;s.cancelled=true;s.started=None;s.recent.clear();}
 pub fn record_failure(&self){let mut s=self.0.lock().unwrap();s.failures=s.failures.saturating_add(1);if s.failures>=MAX_FAILURES{s.permission=Permission::Normal;s.cancelled=true;}}
 pub fn permission(&self)->Permission{self.0.lock().unwrap().permission}
 pub fn consume_capture(&self)->Result<(),String>{let mut s=self.0.lock().unwrap();match s.permission{Permission::SeeScreen=>{s.permission=Permission::Normal;Ok(())},Permission::ControlScreen=>self.check_locked(&mut s),Permission::Normal=>Err("Screen access requires explicit authorization.".into())}}
 fn check_locked(&self,s:&mut Session)->Result<(),String>{if s.cancelled||s.started.is_some_and(|v|v.elapsed()>MAX_SESSION)||s.rounds>=MAX_ROUNDS||s.failures>=MAX_FAILURES{s.permission=Permission::Normal;return Err("Control session ended for safety.".into())}Ok(())}
 pub fn validate(&self,action:&Action)->Result<Decision,String>{let mut s=self.0.lock().unwrap();if s.permission!=Permission::ControlScreen{return Err("Computer control is not authorized.".into())}self.check_locked(&mut s)?;s.rounds+=1;validate_action(action)?;let fingerprint=format!("{action:?}");if s.recent.iter().filter(|v|*v==&fingerprint).count()>=2{return Err("Kai stopped a repeated action loop.".into())}s.recent.push_back(fingerprint);while s.recent.len()>6{s.recent.pop_front();}Ok(if sensitive(action){Decision::Confirm("This action may submit, publish, delete, change an account, or affect security. Confirm this exact action first.".into())}else{Decision::Execute})}
}
fn bounds()->(i32,i32,i32,i32){unsafe{(GetSystemMetrics(SM_XVIRTUALSCREEN),GetSystemMetrics(SM_YVIRTUALSCREEN),GetSystemMetrics(SM_CXVIRTUALSCREEN),GetSystemMetrics(SM_CYVIRTUALSCREEN))}}
fn point_ok(x:i32,y:i32)->bool{let(l,t,w,h)=bounds();x>=l&&x<l.saturating_add(w)&&y>=t&&y<t.saturating_add(h)}
fn allowed_key(key:&str)->bool{matches!(key,"escape"|"enter"|"tab"|"space"|"backspace"|"delete"|"up"|"down"|"left"|"right"|"home"|"end"|"pageup"|"pagedown"|"ctrl"|"alt"|"shift"|"a"|"c"|"v"|"x"|"z")}
fn validate_action(action:&Action)->Result<(),String>{match action{Action::MovePointer{x,y}|Action::Click{x,y}|Action::DoubleClick{x,y}|Action::RightClick{x,y}=>if !point_ok(*x,*y){Err("Pointer coordinates are outside the desktop.".into())}else{Ok(())},Action::SemanticClick{window,name}=>if window.trim().is_empty()||name.trim().is_empty()||window.len()>120||name.len()>120{Err("Semantic UI identity is invalid.".into())}else{Ok(())},Action::Scroll{delta}=>if delta.abs()>2400{Err("Scroll amount is too large.".into())}else{Ok(())},Action::TypeText{text}=>if text.is_empty()||text.len()>MAX_TEXT||text.chars().any(|c|c.is_control()&&!matches!(c,'\n'|'\t')){Err("Typed text is invalid or too long.".into())}else{Ok(())},Action::PressKey{key}=>if allowed_key(&key.to_lowercase()){Ok(())}else{Err("That key is not allowlisted.".into())},Action::KeyCombination{keys}=>if keys.is_empty()||keys.len()>3||keys.iter().any(|k|!allowed_key(&k.to_lowercase())){Err("That key combination is not allowlisted.".into())}else{Ok(())},Action::Wait{milliseconds}=>if *milliseconds>3000{Err("Wait duration is too long.".into())}else{Ok(())},Action::OpenKnownApp{app}=>if matches!(app.as_str(),"calculator"|"notepad"|"explorer"|"settings"|"photoshop"){Ok(())}else{Err("Application is not allowlisted.".into())}}}
fn sensitive(action:&Action)->bool{match action{Action::TypeText{text}=>{let v=text.to_lowercase();["password","send ","publish","purchase","delete","install","permission","account","pay "].iter().any(|x|v.contains(x))},Action::SemanticClick{name,..}=>["send","submit","publish","buy","purchase","delete","remove","install","allow","confirm","pay"].iter().any(|v|name.to_lowercase().contains(v)),Action::PressKey{key}=>key.eq_ignore_ascii_case("enter"),Action::KeyCombination{keys}=>keys.iter().any(|k|k.eq_ignore_ascii_case("enter")),_=>false}}

fn send(inputs:&[INPUT])->Result<(),String>{let sent=unsafe{SendInput(inputs.len() as u32,inputs.as_ptr(),std::mem::size_of::<INPUT>() as i32)};if sent==inputs.len() as u32{Ok(())}else{Err("Windows refused the synthetic input.".into())}}
fn mouse(flags:u32,data:u32)->INPUT{INPUT{r#type:INPUT_MOUSE,Anonymous:INPUT_0{mi:MOUSEINPUT{dx:0,dy:0,mouseData:data,dwFlags:flags,time:0,dwExtraInfo:0}}}}
fn key_input(code:u16,up:bool)->INPUT{INPUT{r#type:INPUT_KEYBOARD,Anonymous:INPUT_0{ki:KEYBDINPUT{wVk:code,wScan:0,dwFlags:if up{KEYEVENTF_KEYUP}else{0},time:0,dwExtraInfo:0}}}}
fn unicode_input(unit:u16,up:bool)->INPUT{INPUT{r#type:INPUT_KEYBOARD,Anonymous:INPUT_0{ki:KEYBDINPUT{wVk:0,wScan:unit,dwFlags:KEYEVENTF_UNICODE|if up{KEYEVENTF_KEYUP}else{0},time:0,dwExtraInfo:0}}}}
fn key_code(key:&str)->Option<u16>{Some(match key.to_lowercase().as_str(){"escape"=>VK_ESCAPE,"enter"=>VK_RETURN,"tab"=>VK_TAB,"space"=>VK_SPACE,"backspace"=>VK_BACK,"delete"=>VK_DELETE,"up"=>VK_UP,"down"=>VK_DOWN,"left"=>VK_LEFT,"right"=>VK_RIGHT,"home"=>VK_HOME,"end"=>VK_END,"pageup"=>VK_PRIOR,"pagedown"=>VK_NEXT,"ctrl"=>VK_CONTROL,"alt"=>VK_MENU,"shift"=>VK_SHIFT,"a"=>VK_A,"c"=>VK_C,"v"=>VK_V,"x"=>VK_X,"z"=>VK_Z,_=>return None})}
pub fn execute(action:&Action)->Result<(),String>{validate_action(action)?;match action{
 Action::MovePointer{x,y}=>if unsafe{SetCursorPos(*x,*y)}!=0{Ok(())}else{Err("Windows couldn't move the pointer.".into())},
 Action::Click{x,y}|Action::DoubleClick{x,y}|Action::RightClick{x,y}=>{if unsafe{SetCursorPos(*x,*y)}==0{return Err("Windows couldn't move the pointer.".into())}let(right,count)=match action{Action::RightClick{..}=>(true,1),Action::DoubleClick{..}=>(false,2),_=>(false,1)};let mut inputs=Vec::new();for _ in 0..count{inputs.push(mouse(if right{MOUSEEVENTF_RIGHTDOWN}else{MOUSEEVENTF_LEFTDOWN},0));inputs.push(mouse(if right{MOUSEEVENTF_RIGHTUP}else{MOUSEEVENTF_LEFTUP},0));}send(&inputs)},
 Action::SemanticClick{window,name}=>{let automation=uiautomation::UIAutomation::new().map_err(|_|"Windows UI Automation is unavailable.")?;let root=automation.get_root_element().map_err(|_|"Windows UI Automation is unavailable.")?;let scope=automation.create_matcher().from(root).name(window).depth(3).timeout(800).find_first().map_err(|_|"The requested window was not found.")?;let element=automation.create_matcher().from(scope).name(name).depth(12).timeout(800).find_first().map_err(|_|"The requested control was not found.")?;element.click().map_err(|_|"The requested control could not be invoked.".into())},
 Action::Scroll{delta}=>send(&[mouse(MOUSEEVENTF_WHEEL,*delta as u32)]),
 Action::TypeText{text}=>{if uiautomation::UIAutomation::new().ok().and_then(|a|a.get_focused_element().ok()).and_then(|e|e.is_password().ok()).unwrap_or(false){return Err("Kai will not type into a password field. Please enter credentials yourself.".into())}let inputs=text.encode_utf16().flat_map(|unit|[unicode_input(unit,false),unicode_input(unit,true)]).collect::<Vec<_>>();send(&inputs)},
 Action::PressKey{key}=>{let code=key_code(key).ok_or("That key is not allowlisted.")?;send(&[key_input(code,false),key_input(code,true)])},
 Action::KeyCombination{keys}=>{let codes=keys.iter().map(|k|key_code(k).ok_or("That key is not allowlisted.")).collect::<Result<Vec<_>,_>>()?;let mut inputs=codes.iter().map(|v|key_input(*v,false)).collect::<Vec<_>>();inputs.extend(codes.iter().rev().map(|v|key_input(*v,true)));send(&inputs)},
 Action::Wait{milliseconds}=>{std::thread::sleep(Duration::from_millis(*milliseconds));Ok(())},Action::OpenKnownApp{..}=>Ok(())}}

#[cfg(test)] mod tests{use super::*;#[test]fn needs_authorization(){let s=ControlState::default();assert!(s.validate(&Action::Scroll{delta:1}).is_err())}#[test]fn rejects_bounds_and_text(){assert!(validate_action(&Action::MovePointer{x:i32::MAX,y:0}).is_err());assert!(validate_action(&Action::TypeText{text:"x".repeat(501)}).is_err())}#[test]fn rejects_keys_and_apps(){assert!(validate_action(&Action::PressKey{key:"f12".into()}).is_err());assert!(validate_action(&Action::OpenKnownApp{app:"powershell".into()}).is_err())}#[test]fn confirms_sensitive(){let s=ControlState::default();s.start();assert!(matches!(s.validate(&Action::PressKey{key:"enter".into()}),Ok(Decision::Confirm(_))))}#[test]fn stops_loops(){let s=ControlState::default();s.start();let a=Action::Scroll{delta:10};assert!(s.validate(&a).is_ok());assert!(s.validate(&a).is_ok());assert!(s.validate(&a).is_err())}#[test]fn one_shot_capture_is_consumed(){let s=ControlState::default();s.authorize_once();assert!(s.consume_capture().is_ok());assert!(s.consume_capture().is_err())}#[test]fn stop_and_failures_release_permission(){let s=ControlState::default();s.start();s.stop();assert_eq!(s.permission(),Permission::Normal);s.start();s.record_failure();s.record_failure();s.record_failure();assert_eq!(s.permission(),Permission::Normal)}#[test]fn round_limit_ends_session(){let s=ControlState::default();s.start();for i in 0..MAX_ROUNDS{assert!(s.validate(&Action::Wait{milliseconds:i as u64}).is_ok())}assert!(s.validate(&Action::Wait{milliseconds:100}).is_err())}}
